Refactor this async Rust service into idiomatic Rust 2024 style — it compiles but clippy is screaming at me and I know the error handling is a mess. The service fetches sensor readings from multiple IoT devices concurrently, aggregates them, and writes summaries to a PostgreSQL database. Here's the current code:
```rust
use tokio;
use sqlx;
use reqwest;
use std::collections::HashMap;
use serde::{Deserialize, Serialize};

#[derive(Debug, Deserialize, Clone)]
struct SensorReading {
    device_id: String,
    temperature: f64,
    humidity: f64,
    timestamp: i64,
}

#[derive(Debug, Serialize)]
struct AggregatedSummary {
    avg_temperature: f64,
    avg_humidity: f64,
    device_count: i32,
    window_start: i64,
    window_end: i64,
}

async fn fetch_sensor_data(client: &reqwest::Client, url: String) -> Result<SensorReading, Box<dyn std::error::Error + Send + Sync>> {
    let resp = client.get(&url).send().await?;
    let body = resp.text().await?;
    let reading: SensorReading = serde_json::from_str(&body)?;
    return Ok(reading);
}

async fn fetch_all_sensors(device_urls: Vec<String>) -> Vec<SensorReading> {
    let client = reqwest::Client::new();
    let mut handles = vec![];

    for url in device_urls.clone() {
        let c = client.clone();
        let u = url.clone();
        let handle = tokio::spawn(async move {
            let result = fetch_sensor_data(&c, u).await;
            match result {
                Ok(r) => Some(r),
                Err(e) => {
                    println!("Error fetching sensor: {}", e);
                    None
                }
            }
        });
        handles.push(handle);
    }

    let mut readings: Vec<SensorReading> = vec![];
    for handle in handles {
        match handle.await {
            Ok(maybe_reading) => {
                match maybe_reading {
                    Some(r) => readings.push(r),
                    None => {}
                }
            }
